{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Vol Desk Data",
    "operation": "add",
    "url": "http://localhost:7801",
    "widgets_json": {
      "vol_regime_metric": {
        "name": "Vol Regime",
        "description": "Current volatility regime score.",
        "endpoint": "/vol-regime",
        "type": "metric",
        "params": [
          {
            "paramName": "regime_view",
            "type": "text",
            "label": "Regime View",
            "value": "summary",
            "description": "Vol regime view to show."
          }
        ],
        "staleTime": 900000,
        "runButton": true,
        "w": 6,
        "h": 4
      },
      "vol_commentary": {
        "name": "Vol Commentary",
        "description": "Morning volatility commentary.",
        "endpoint": "/vol-commentary",
        "type": "markdown",
        "params": [
          {
            "paramName": "desk",
            "type": "text",
            "label": "Desk",
            "options": [
              { "label": "Index", "value": "index" },
              { "label": "Single Stock", "value": "single" }
            ],
            "value": "index",
            "description": "Desk for commentary."
          }
        ],
        "staleTime": 900000,
        "runButton": true,
        "w": 12,
        "h": 8
      },
      "vix_history": {
        "name": "VIX History",
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "type": "table",
        "params": [
          {
            "paramName": "window",
            "type": "number",
            "label": "Window",
            "value": 30,
            "min": 5,
            "max": 365
          }
        ],
        "staleTime": 900000,
        "runButton": true,
        "w": 20,
        "h": 9,
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "date",
                "headerName": "Date",
                "cellDataType": "dateString"
              },
              {
                "field": "close",
                "headerName": "Close",
                "cellDataType": "number"
              },
              {
                "field": "return_pct",
                "headerName": "Return %",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed"
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Vol Config Live",
        "description": "Configured vol metric and commentary.",
        "tabs": {
          "vol": {
            "id": "vol",
            "name": "Vol",
            "layout": [
              {
                "i": "vol_regime_metric",
                "x": 0,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          },
          "posture": {
            "id": "posture",
            "name": "Posture",
            "layout": [
              {
                "i": "vol_commentary",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        }
      }
    ]
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "dashboard_name": "Vol Config Live Board",
    "app_name": "Vol Config Live"
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "app_name": "Vol Config Live",
    "dashboard_name": "Vol Config Live Board",
    "backend_id": "backend_001"
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "data": "Vol Config Live shipped from Vol Desk Data: staleTime 900000.",
    "inner_tab": "vol",
    "name": "Vol Config Live",
    "widget_type": "note"
  }
}
